"""Environment smoke tests: the toolchain the prototype depends on is present."""

import shutil
import subprocess

import numpy as np
import pytest


def test_numpy_seeded_rng_is_deterministic() -> None:
    a = np.random.default_rng(0).standard_normal(8)
    b = np.random.default_rng(0).standard_normal(8)
    assert np.array_equal(a, b)


@pytest.mark.skipif(shutil.which("ffmpeg") is None, reason="ffmpeg not installed")
def test_ffmpeg_decodes_to_mono_11025_f32() -> None:
    # 1 s of a 440 Hz sine generated by ffmpeg, decoded with the spec's exact flags.
    cmd = [
        "ffmpeg",
        "-v",
        "error",
        "-f",
        "lavfi",
        "-i",
        "sine=frequency=440:sample_rate=44100:duration=1",
        "-ac",
        "1",
        "-ar",
        "11025",
        "-f",
        "f32le",
        "-",
    ]
    pcm = np.frombuffer(subprocess.run(cmd, check=True, capture_output=True).stdout, np.float32)
    assert abs(len(pcm) - 11025) <= 64
    spectrum = np.abs(np.fft.rfft(pcm))
    peak_hz = np.argmax(spectrum) * 11025 / len(pcm)
    assert abs(peak_hz - 440) < 5
